update public.invoice_contents set assigned_by='Anamm' where invoice_id=(select id from public.invoices where invoice_number='160' limit 1) and title='Rahul Mishra';
update public.invoice_contents set assigned_by='Ekta' where invoice_id=(select id from public.invoices where invoice_number='160' limit 1) and title in ('Sid Shriram / Mathew Iffield / Gini','Sid Shriram + Mathew Iffield + Gini','Saif Kareena','Rhea Raj','Avan & Dove ''56 Days''');
update public.invoice_contents set title='Sid Shriram + Mathew Iffield + Gini' where invoice_id=(select id from public.invoices where invoice_number='160' limit 1) and title='Sid Shriram / Mathew Iffield / Gini';
update public.invoice_contents set title='Bhumi + Lolla @3 Videos + BaladBeast @3 Videos' where invoice_id=(select id from public.invoices where invoice_number='106' limit 1) and title='Bhumi + Lolla (3 Videos) + BaladBeast (3 Videos)';
update public.invoice_contents set position=case title when 'Bridgerton (2 Videos)' then 0 when 'Aneet Padda' then 1 when 'Ibrahim Ali Khan & Pratibha Ranta' then 2 when 'Jeff Satur' then 3 when 'Reble' then 4 when 'The Devil Wears Prada 2' then 5 when 'Salim Merchant' then 6 when 'Akhil Sahni' then 7 when 'Nora' then 8 when 'Coo Heart' then 9 else position end where invoice_id=(select id from public.invoices where invoice_number='180' limit 1);
update public.invoice_versions iv set snapshot=public.invoice_snapshot(iv.invoice_id),snapshot_hash=encode(digest(public.invoice_snapshot(iv.invoice_id)::text,'sha256'),'hex') where iv.invoice_id in (select id from public.invoices where invoice_number in ('106','160','180','220')) and iv.version_number in (select issued_version from public.invoices where id=iv.invoice_id);
update public.documents d set source_hash=iv.snapshot_hash from public.invoice_versions iv where d.invoice_id=iv.invoice_id and d.version_number=iv.version_number and d.document_type='invoice_pdf' and d.invoice_id in (select id from public.invoices where invoice_number in ('106','160','180','220'));